(() => {
'use strict';
const S={csrf:'',data:null,tab:'dashboard',workspaceView:{desktop:'new',android:'new'},software:[],softwareIndex:new Map(),activeClaims:new Map(),releasePromises:new Map(),detail:null,users:[],recentActivity:[],activityFilters:null,notificationItems:[],notificationPoll:null,lastNotificationId:0,mobile:false,newFilter:'newest',newCategory:'all',publishedFilter:'newest',publishedCategory:'all',detailPollToken:0,importPollToken:0,detailHeartbeat:null,claimPoll:null,newLimit:300,publishedLimit:300};

/* ---- Theme: light by default, respects saved choice, real toggle ---- */
const THEME_KEY='hsware-theme';
function applyTheme(mode){
  document.documentElement.dataset.theme=mode;
  const meta=document.querySelector('meta[name="theme-color"]');
  if(meta)meta.setAttribute('content',mode==='dark'?'#0A0B0D':'#FFFFFF');
}
function currentTheme(){try{return localStorage.getItem(THEME_KEY)==='dark'?'dark':'light'}catch{return'light'}}
function setTheme(mode){try{localStorage.setItem(THEME_KEY,mode)}catch{}applyTheme(mode);const t=$('#themeToggle');if(t)t.classList.toggle('on',mode==='dark')}
applyTheme(currentTheme());

const $=s=>document.querySelector(s); const app=$('#app');

/* ---- Icon set: inline SVG, currentColor, replaces every glyph icon ---- */
const ICONS={
  home:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M4 11.5 12 4l8 7.5"/><path d="M6 10v9a1 1 0 0 0 1 1h4v-6h2v6h4a1 1 0 0 0 1-1v-9"/></svg>',
  plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>',
  check:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5 9.5 17 19 7"/></svg>',
  refresh:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M20 11a8 8 0 1 0-2.2 5.7"/><path d="M20 5v6h-6"/></svg>',
  settings:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 13a1.7 1.7 0 0 0 .34 1.87l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.7 1.7 0 0 0-1.87-.34 1.7 1.7 0 0 0-1 1.55V19a2 2 0 1 1-4 0v-.09a1.7 1.7 0 0 0-1.1-1.55 1.7 1.7 0 0 0-1.87.34l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.7 1.7 0 0 0 .34-1.87 1.7 1.7 0 0 0-1.55-1H4a2 2 0 1 1 0-4h.09a1.7 1.7 0 0 0 1.55-1.1 1.7 1.7 0 0 0-.34-1.87l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.7 1.7 0 0 0 1.87.34H10a1.7 1.7 0 0 0 1-1.55V4a2 2 0 1 1 4 0v.09a1.7 1.7 0 0 0 1 1.55 1.7 1.7 0 0 0 1.87-.34l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.7 1.7 0 0 0-.34 1.87V10a1.7 1.7 0 0 0 1.55 1H20a2 2 0 1 1 0 4h-.09a1.7 1.7 0 0 0-1.51 1z"/></svg>',
  pulse:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12h4l2.5-7 4 14L16 12h5"/></svg>',
  bell:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg>',
  logout:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="M16 17l5-5-5-5"/><path d="M21 12H9"/></svg>',
  menu:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg>',
  close:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg>',
  search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/></svg>',
  arrowRight:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>',
  sun:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>',
  moon:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M20.5 14.5A8.5 8.5 0 1 1 9.5 3.5a7 7 0 0 0 11 11z"/></svg>',
  desktop:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/></svg>',
  android:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><rect x="7" y="3" width="10" height="18" rx="2"/><path d="M10 6h4M11 18h2"/></svg>',
  ready:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5 9.5 17 19 7"/></svg>',
  shield:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3 5 6v5c0 5.25 3.45 8.86 7 10 3.55-1.14 7-4.75 7-10V6l-7-3Z"/></svg>',
};
const icon=(name,extra='')=>`<span class="icon"${extra?` ${extra}`:''}>${ICONS[name]||''}</span>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>{const raw=String(v||'').trim();if(!/^https?:\/\//i.test(raw))return'';try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)?u.toString():''}catch{return''}};
const fmt=n=>Number(n||0).toLocaleString();
const count=n=>n==null?'Public total unavailable':Number(n).toLocaleString();
const bytes=n=>{n=Number(n||0);if(!n)return'N/A';const u=['B','KB','MB','GB'];const i=Math.min(3,Math.floor(Math.log(n)/Math.log(1024)));return`${(n/(1024**i)).toFixed(i?1:0)} ${u[i]}`};
const dateLabel=v=>{if(!v)return'N/A';const d=new Date(`${String(v).slice(0,10)}T00:00:00`);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})};
const dateTimeLabel=v=>{if(!v)return'No backup yet';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})};
const relativeTime=v=>{if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return'';const sec=Math.max(0,Math.floor((Date.now()-d.getTime())/1000));if(sec<45)return'Just now';if(sec<3600)return`${Math.floor(sec/60)} min ago`;if(sec<86400)return`${Math.floor(sec/3600)} hr ago`;if(sec<604800)return`${Math.floor(sec/86400)} day${Math.floor(sec/86400)===1?'':'s'} ago`;return d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:d.getFullYear()===new Date().getFullYear()?undefined:'numeric'})};
const localeName=code=>{const raw=String(code||'').trim();if(!raw)return'';try{const base=raw.split(/[-_]/)[0];const names=new Intl.DisplayNames([navigator.language||'en'],{type:'language'});return names.of(base)||base}catch{return raw.split(/[-_]/)[0]}};
const languageLabel=()=> 'English';
const isLiteApks=x=>String(x?.sourceType||'').toLowerCase()==='liteapks'||String(x?.platformKey||'').toLowerCase()==='android';
const sourceReady=x=>isLiteApks(x)?Boolean(safeUrl(x?.sourcePageUrl)):Boolean(safeUrl(x?.installerUrl));
const platformLabel=x=>isLiteApks(x)?'Android':'Windows';
const packageDisplay=x=>isLiteApks(x)?(x?.sourcePackageId||String(x?.packageId||'').replace(/^liteapks:/,'')):x?.packageId;
const processorLabel=x=>{const a=String(x?.architecture||'').toLowerCase();if(a.includes('arm64'))return'ARM64';if(a==='x86'||a.includes('32'))return'x86';if(a.includes('x64')||a.includes('64'))return'x64';const p=String(x?.processor||'').toLowerCase();if(p.includes('arm64'))return'ARM64';if(/32-bit|x86/.test(p))return'x86';if(/64-bit|x64/.test(p))return'x64';return'x64'};
const storageLabel=v=>{const raw=String(v||'').trim();if(!raw)return'Automatic';const m=raw.match(/([\d.]+)\s*(TB|GB|MB|KB)/i);return m?`${m[1]} ${m[2].toUpperCase()}`:raw.replace(/\b(available|free|required|storage|disk space|space)\b/gi,'').replace(/\s{2,}/g,' ').trim()||'Automatic'};
const osLabel=v=>{const raw=String(v||'').trim();if(!raw)return'Windows 10 or newer';const m=raw.match(/^10\.0\.(\d+)(?:\.\d+)?$/);if(m)return`Windows 10/11 — build ${m[1]} or newer (${raw})`;const map={'6.3':'Windows 8.1','6.2':'Windows 8','6.1':'Windows 7','6.0':'Windows Vista','5.1':'Windows XP'};const key=Object.keys(map).find(k=>raw===k||raw.startsWith(`${k}.`));return key?`${map[key]} or newer (${raw})`:raw};
const enrichedRevision=x=>Number(x?.metadataRevision||0)>=2;
const requirementValue=(x,v)=>v||'Automatic';
const estimateMark=(x,key)=>x?.requirementEstimates?.[key]?'Auto':'';
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function toast(msg,type='info',title=''){document.querySelectorAll('.toast').forEach(x=>x.remove());const t=document.createElement('div');t.className=`toast toast-${esc(type)}`;t.innerHTML=`<span class="toast-mark"></span><div><div class="toast-title">${esc(title||msg)}</div>${title?`<div class="toast-message">${esc(msg)}</div>`:''}</div>`;document.body.appendChild(t);setTimeout(()=>t.remove(),4200)}
async function copyText(text){const value=String(text||'');if(!value)return toast('Nothing to copy');try{await navigator.clipboard.writeText(value);toast('Copied')}catch{const ta=document.createElement('textarea');ta.value=value;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('Copied')}}
async function API(url,opt={}){const headers=new Headers(opt.headers||{});if(opt.body&&!headers.has('content-type')&&typeof opt.body==='string')headers.set('content-type','application/json');if(S.csrf&&opt.method&&opt.method!=='GET')headers.set('x-csrf-token',S.csrf);const r=await fetch(url,{credentials:'same-origin',...opt,headers});const ct=r.headers.get('content-type')||'';const d=ct.includes('json')?await r.json():{error:await r.text()};if(!r.ok||d.ok===false){const err=new Error(d.error||`Request failed (${r.status})`);err.status=r.status;err.data=d;throw err}return d}
async function bootstrap(){const d=await API('/api/bootstrap');S.csrf=d.csrfToken;S.data=d;return d}
const isAdmin=()=>S.data?.user?.role==='admin';
const initials=name=>String(name||'User').trim().split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join('')||'U';
function avatarHtml(u,cls='profile-avatar'){return u?.hasAvatar&&u?.avatarUrl?`<img class="${cls}" src="${esc(u.avatarUrl)}" alt="${esc(u.name||'User')}">`:`<div class="${cls} avatar-fallback">${esc(initials(u?.name))}</div>`}
function normalizeRole(role){return String(role||'partner').toLowerCase()==='admin'?'admin':'partner'}
function profileRoleMarkup(u){const active=normalizeRole(u?.role||u?.roleLabel);const label=active==='admin'?'Admin':'Partner';return`<div class="profile-role-row"><span class="profile-role-pill ${active}"><span class="profile-role-icon">${icon('shield')}</span><span class="profile-role-current">${label}</span></span></div>`}
function profileCardInner(u){return`<div class="profile-top"><div class="profile-media">${avatarHtml(u)}</div><div class="profile-main"><div class="profile-name">${esc(u?.name||'HSWare User')}</div><div class="profile-email" title="${esc(u?.email||'')}">${esc(u?.email||'Signed in')}</div>${profileRoleMarkup(u)}</div></div><div class="profile-divider"></div><button class="profile-signout" id="logout" title="Sign out" aria-label="Sign out">${icon('logout')}<span>Logout</span></button>`}
const workspaceMeta={
  desktop:{platform:'windows',title:'Desktop Software',sub:'Windows software workspace powered by WinGet.',newLabel:'New Software',publishedLabel:'Published Software',updatesLabel:'Software Updates'},
  android:{platform:'android',title:'Android APK',sub:'Android APK workspace sourced from LiteAPKs.',newLabel:'New APK',publishedLabel:'Published APK',updatesLabel:'APK Updates'}
};
function currentWorkspace(){return S.tab==='desktop'||S.tab==='android'?S.tab:null}
function workspaceView(section=currentWorkspace()){return section?S.workspaceView[section]||'new':'new'}
function workspaceScope(view){return view==='published'?'published':view==='updates'?'updates':'unpublished'}
function workspaceInfo(section=currentWorkspace()){return workspaceMeta[section]||workspaceMeta.desktop}
function headerCopy(){
  if(S.tab==='dashboard')return['Dashboard','Desktop software and Android APK publishing are managed separately.'];
  if(S.tab==='settings')return['Settings','Team access, backup and deployment controls.'];
  const info=workspaceInfo();const view=workspaceView();const label=view==='published'?info.publishedLabel:view==='updates'?info.updatesLabel:info.newLabel;
  return[`${info.title} · ${label}`,info.sub];
}
function navItem(tab,label,iconName,badge=''){return`<button class="nav-btn ${S.tab===tab?'active':''}" data-nav="${tab}"><span><span class="nav-icon">${icon(iconName)}</span>${esc(label)}</span>${badge!==''?`<span class="badge">${fmt(badge)}</span>`:''}</button>`}
function shell(){const d=S.data,c=d.counts||{},u=d.user||{},admin=isAdmin();const dark=currentTheme()==='dark';const unread=Number(d.notificationSummary?.unreadCount||0);const systemNav=admin?`<div class="nav-label">System</div>${navItem('settings','Settings','settings')}<button class="nav-btn" id="openHealth"><span><span class="nav-icon">${icon('pulse')}</span>Database Health</span></button>`:'';app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="side-scroll"><div class="brand"><img class="brand-logo" src="/ui/assets/hsware-logo.png" alt="HSWare"><div class="brand-copy"><div class="brand-title">HSWare Studio <span class="version">v4.5</span></div><div class="brand-sub">Software Publishing Workspace</div></div></div><div class="nav-label">Workspace</div>${navItem('dashboard','Dashboard','home')}${navItem('desktop','Desktop Software','desktop',c.desktopUnpublished)}${navItem('android','Android APK','android',c.androidUnpublished)}${systemNav}<div class="nav-label">Appearance</div><button class="theme-toggle ${dark?'on':''}" id="themeToggle"><span class="nav-icon">${icon(dark?'moon':'sun')}</span><span>${dark?'Dark mode':'Light mode'}</span><span class="theme-switch"><span></span></span></button></div><div class="sidebar-foot"><div class="profile-card">${profileCardInner(u)}</div></div></aside><main class="main"><header class="topbar"><div style="display:flex;gap:10px;align-items:center;min-width:0"><button class="btn icon-btn mobile-menu" id="mobileMenu">${icon('menu')}</button><div><div><span class="top-title" id="topTitle"></span><span class="live"><span class="live-dot"></span>Live Database</span></div><div class="top-sub" id="topSub"></div></div></div><div class="actions"><button class="notification-bell" id="notificationBell" title="Notifications" aria-label="Notifications">${icon('bell')}<span class="notification-count ${unread?'show':''}" id="notificationCount">${unread>99?'99+':unread}</span></button>${admin?'<button class="btn hide-mobile" id="healthBtn">Health</button>':''}<button class="btn primary" id="newBtn">${icon('plus')} New Software</button></div></header><div class="content" id="content"></div></main></div>`;bindShell();updateHeader();if(admin)showBackupNotification()}
function updateHeader(){const [t,s]=headerCopy();$('#topTitle').textContent=t;$('#topSub').textContent=s;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===S.tab));const btn=$('#newBtn');if(btn){const android=S.tab==='android';btn.innerHTML=`${icon('plus')} ${android?'New APK':'New Software'}`}}
function bindProfileCardActions(){const logoutBtn=$('#logout');if(logoutBtn)logoutBtn.onclick=async()=>{try{await API('/api/logout',{method:'POST',body:'{}'});location.href='/login'}catch(e){toast(e.message)}}}
function bindShell(){document.addEventListener('click',async e=>{const n=e.target.closest('[data-nav]');if(n){await go(n.dataset.nav);return}}, {once:false});$('#notificationBell').onclick=openNotificationPanel;$('#newBtn').onclick=()=>go(S.tab==='android'?'android':'desktop','new');if($('#healthBtn'))$('#healthBtn').onclick=healthModal;if($('#openHealth'))$('#openHealth').onclick=healthModal;$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#themeToggle').onclick=()=>{const next=currentTheme()==='dark'?'light':'dark';setTheme(next);const t=$('#themeToggle');t.querySelector('.nav-icon').innerHTML=ICONS[next==='dark'?'moon':'sun'];t.querySelector('span:nth-child(2)').textContent=next==='dark'?'Dark mode':'Light mode'};bindProfileCardActions()}
function updateProfileCard(){const u=S.data?.user||{};const card=$('.profile-card');if(!card)return;card.innerHTML=profileCardInner(u);bindProfileCardActions()}
function updateNotificationBell(summary=S.data?.notificationSummary||{}){const unread=Number(summary.unreadCount||0);if(S.data)S.data.notificationSummary={...(S.data.notificationSummary||{}),...summary};const b=$('#notificationCount');if(b){b.textContent=unread>99?'99+':String(unread);b.classList.toggle('show',unread>0)}}
async function refreshBootstrap(){const d=await API('/api/bootstrap');S.csrf=d.csrfToken;S.data=d;const c=d.counts||{};document.querySelectorAll('[data-nav="desktop"] .badge').forEach(x=>x.textContent=fmt(c.desktopUnpublished));document.querySelectorAll('[data-nav="android"] .badge').forEach(x=>x.textContent=fmt(c.androidUnpublished));updateProfileCard();updateNotificationBell(d.notificationSummary)}
function notificationTone(type){const t=String(type||'info').toLowerCase();return['success','warning','error','info'].includes(t)?t:'info'}
function notificationRowHtml(n){const tone=notificationTone(n.type);return`<div class="notification-row ${n.isRead?'':'unread'}" data-notification-id="${n.id}"><span class="notification-dot ${tone}"></span><div class="notification-copy"><div class="notification-title">${esc(n.title)}</div><div class="notification-message">${esc(n.message||'')}</div><div class="notification-meta">${n.actorName?`${esc(n.actorName)} · `:''}${esc(relativeTime(n.createdAt))}${n.softwareName?` · ${esc(n.softwareName)}`:''}</div></div><div class="notification-actions">${n.softwareId?`<button class="link-button" data-notification-open="${n.softwareId}" data-notification-read="${n.id}">Open</button>`:''}${n.isRead?'':`<button class="link-button" data-notification-read="${n.id}">Read</button>`}</div></div>`}
async function markNotificationRead(ids){const clean=[...new Set((Array.isArray(ids)?ids:[ids]).map(Number).filter(Boolean))];if(!clean.length)return;const d=await API('/api/notifications/read',{method:'POST',body:JSON.stringify({ids:clean})});updateNotificationBell(d.summary||{});S.notificationItems=S.notificationItems.map(n=>clean.includes(Number(n.id))?{...n,isRead:true}:n)}
function bindNotificationRows(root){root.querySelectorAll('[data-notification-read]').forEach(btn=>btn.onclick=async e=>{e.stopPropagation();const id=Number(btn.dataset.notificationRead);try{await markNotificationRead(id);const row=btn.closest('.notification-row');if(row){row.classList.remove('unread');row.querySelectorAll('[data-notification-read]').forEach(x=>{if(!x.dataset.notificationOpen)x.remove()})}}catch(err){toast(err.message,'error')}});root.querySelectorAll('[data-notification-open]').forEach(btn=>btn.onclick=async e=>{e.stopPropagation();const id=Number(btn.dataset.notificationRead);try{await markNotificationRead(id)}catch{}$('#notificationPanel')?.remove();await openDetail(Number(btn.dataset.notificationOpen))})}
async function loadNotificationPanel(){const body=$('#notificationList');if(!body)return;try{const d=await API('/api/notifications?limit=30');S.notificationItems=d.items||[];updateNotificationBell(d.summary||{});body.innerHTML=S.notificationItems.length?S.notificationItems.map(notificationRowHtml).join(''):'<div class="notification-empty">You are all caught up.</div>';bindNotificationRows(body)}catch(e){body.innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function openNotificationPanel(){const existing=$('#notificationPanel');if(existing){existing.remove();return}document.body.insertAdjacentHTML('beforeend',`<section class="notification-panel" id="notificationPanel"><div class="notification-head"><div><div class="notification-heading">Notifications</div><div class="notification-sub">Important HSWare activity and completed background work.</div></div><button class="btn icon-btn" id="notificationClose" aria-label="Close">${icon('close')}</button></div><div class="notification-list" id="notificationList"><div class="notification-empty">Loading…</div></div><div class="notification-foot"><button class="link-button" id="markAllNotifications">Mark all as read</button></div></section>`);$('#notificationClose').onclick=()=>$('#notificationPanel')?.remove();$('#markAllNotifications').onclick=async()=>{try{const d=await API('/api/notifications/read',{method:'POST',body:JSON.stringify({all:true})});updateNotificationBell(d.summary||{});await loadNotificationPanel()}catch(e){toast(e.message,'error')}};await loadNotificationPanel()}
async function pollNotifications(){try{const d=await API('/api/notifications/summary');const latest=Number(d.latestId||0);if(latest>S.lastNotificationId){const fresh=await API('/api/notifications?limit=1&unreadOnly=1');const item=fresh.items?.[0];if(item&&Number(item.id)>S.lastNotificationId)toast(item.message||item.title,notificationTone(item.type),item.title);S.lastNotificationId=Math.max(latest,S.lastNotificationId);if($('#notificationPanel'))await loadNotificationPanel()}updateNotificationBell(d)}catch{}}
function startNotificationPoll(){if(S.notificationPoll)clearInterval(S.notificationPoll);S.lastNotificationId=Number(S.data?.notificationSummary?.latestId||0);S.notificationPoll=setInterval(pollNotifications,15000)}
async function loadSoftware(scope='all',platform='all'){const d=await API(`/api/software?scope=${encodeURIComponent(scope)}&platform=${encodeURIComponent(platform)}`);S.software=d.results||[];S.softwareIndex=new Map(S.software.map(x=>[Number(x.id),x]));S.activeClaims=new Map(S.software.filter(x=>x.claim).map(x=>[Number(x.id),x.claim]));return S.software}
async function loadRecentActivity(){try{const d=await API('/api/activity?limit=8&offset=0');S.recentActivity=d.results||[]}catch(e){S.recentActivity=[];console.warn('Recent Activity unavailable:',e.message)}}
function workspaceTabs(section){const info=workspaceInfo(section),view=workspaceView(section),c=S.data?.counts||{};const counts=section==='android'?{new:c.androidUnpublished,published:c.androidPublished,updates:c.androidUpdates}:{new:c.desktopUnpublished,published:c.desktopPublished,updates:c.desktopUpdates};const labels={new:info.newLabel,published:info.publishedLabel,updates:info.updatesLabel};return`<div class="workspace-tabbar"><div class="tabs workspace-tabs">${['new','published','updates'].map(v=>`<button class="tab ${view===v?'active':''}" data-workspace-view="${v}"><span>${esc(labels[v])}</span><span class="workspace-tab-count">${fmt(counts[v])}</span></button>`).join('')}</div></div>`}
function bindWorkspaceTabs(root,section){root.querySelectorAll('[data-workspace-view]').forEach(btn=>btn.onclick=()=>go(section,btn.dataset.workspaceView))}
async function go(tab,subtab=null){if(tab==='settings'&&!isAdmin()){toast('Settings are available to the Admin only');tab='dashboard'}if(!['dashboard','desktop','android','settings'].includes(tab))tab='dashboard';const previousTab=S.tab;if((tab==='desktop'||tab==='android')&&['new','published','updates'].includes(subtab||''))S.workspaceView[tab]=subtab;if((tab==='desktop'||tab==='android')&&tab!==previousTab){S.newFilter='newest';S.newCategory='all';S.publishedFilter='newest';S.publishedCategory='all';S.newLimit=300;S.publishedLimit=300}S.tab=tab;$('#sidebar')?.classList.remove('open');updateHeader();const content=$('#content');if(!content.innerHTML.trim())content.innerHTML='<div class="notice">Loading…</div>';try{if(tab==='dashboard'){await Promise.all([loadSoftware('all','all'),loadRecentActivity()]);renderDashboard()}else if(tab==='desktop'||tab==='android'){const view=workspaceView(tab);await loadSoftware(workspaceScope(view),workspaceInfo(tab).platform);renderWorkspace(tab)}else if(tab==='settings'){await loadUsers();renderSettings()}}catch(e){content.innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
function stats(){const c=S.data.counts||{};const cards=[['desktop','new','New Software',c.desktopUnpublished,'Windows queue','plus'],['desktop','published','Published Software',c.desktopPublished,'Windows library','check'],['desktop','updates','Software Updates',c.desktopUpdates,'Windows updates','refresh'],['android','new','New APK',c.androidUnpublished,'LiteAPKs queue','plus'],['android','published','Published APK',c.androidPublished,'Android library','check'],['android','updates','APK Updates',c.androidUpdates,'Android updates','refresh']];return`<div class="stats">${cards.map(x=>`<button class="stat" data-stat-section="${x[0]}" data-stat-view="${x[1]}"><div class="stat-head"><span class="stat-icon">${icon(x[5])}</span>${x[2]}</div><div class="stat-num">${fmt(x[3])}</div><div class="stat-sub">${x[4]}</div></button>`).join('')}</div>`}
function renderDashboard(){const c=$('#content');const desktop=S.software.filter(x=>!x.published&&!isLiteApks(x)).slice(0,8);const android=S.software.filter(x=>!x.published&&isLiteApks(x)).slice(0,8);c.innerHTML=stats()+softwarePanel(desktop,'Desktop Priority Queue','Recently imported Windows software waiting for publishing.')+softwarePanel(android,'Android APK Priority Queue','Recently discovered LiteAPKs records waiting for publishing.')+activityPanel(S.recentActivity);c.querySelectorAll('[data-stat-section]').forEach(b=>b.onclick=()=>go(b.dataset.statSection,b.dataset.statView));bindSoftwareRows(c);const all=$('#viewAllActivity');if(all)all.onclick=openActivityModal}
function activityPanel(items=[]){return`<section class="panel activity-panel"><div class="panel-head"><div><div class="panel-title">Recent Activity <span class="status draft">${fmt(items.length)}</span></div><div class="panel-sub">Meaningful workspace actions from Admin, Partners, imports, publishing and updates.</div></div><button class="btn" id="viewAllActivity">View All Activity</button></div><div class="activity-list">${items.length?items.map(activityRowHtml).join(''):'<div class="empty">No recorded activity yet.</div>'}</div></section>`}
function activityIconClass(category){
  const value=String(category||'').toLowerCase();
  if(value.includes('publish')) return 'success';
  if(value.includes('update')) return 'refresh';
  if(value.includes('import')) return 'import';
  if(value.includes('delete')||value.includes('remove')) return 'danger';
  return 'default';
}
function activityText(a){
  const action=String(a.action||a.category||'Activity').replace(/[_-]+/g,' ');
  const name=a.packageName||a.softwareName||a.packageId||'item';
  return `${action} ${name}`;
}
function activityRowHtml(a){return`<div class="activity-row"><span class="activity-dot ${activityIconClass(a.category)}"></span><div class="activity-copy"><div class="activity-title">${esc(activityText(a))}</div><div class="activity-meta"><span>${esc(a.userName||'System')}${a.userRole?` · ${esc(a.userRole==='admin'?'Admin':'Partner')}`:''}</span><span>·</span><span title="${esc(dateTimeLabel(a.createdAt))}">${esc(relativeTime(a.createdAt))}</span>${a.packageId?`<span>·</span><span class="code">${esc(a.packageId)}</span>`:''}</div></div></div>`}
async function fetchActivity({offset=0}={}){const wrap=$('#activityWrap');if(!wrap)return;const q=String($('#activitySearch')?.value||'').trim();const action=String($('#activityAction')?.value||'');const userId=String($('#activityUser')?.value||'');const from=String($('#activityFrom')?.value||'');const to=String($('#activityTo')?.value||'');const params=new URLSearchParams({limit:'40',offset:String(offset)});if(q)params.set('q',q);if(action)params.set('action',action);if(userId)params.set('userId',userId);if(from)params.set('from',from);if(to)params.set('to',to);const d=await API(`/api/activity?${params}`);S.activityFilters=d.filters||S.activityFilters;renderActivityModalResults(d,offset)}
function activityActionOptions(filters,selected=''){return(filters?.actions||[]).map(x=>`<option value="${esc(x.action)}" ${x.action===selected?'selected':''}>${esc(x.label)}</option>`).join('')}
function activityUserOptions(filters,selected=''){return(filters?.users||[]).map(x=>`<option value="${x.id}" ${String(x.id)===String(selected)?'selected':''}>${esc(x.name)} · ${esc(x.role==='admin'?'Admin':'Partner')}</option>`).join('')}
function renderActivityModalResults(d,offset=0){const body=$('#activityResults');if(!body)return;const items=d.results||[];body.innerHTML=items.length?items.map(activityRowHtml).join(''):'<div class="empty">No activity matches these filters.</div>';const total=Number(d.total||0),limit=Number(d.limit||40);const page=$('#activityPageInfo');if(page)page.textContent=`${total?offset+1:0}–${Math.min(offset+items.length,total)} of ${fmt(total)}`;const prev=$('#activityPrev'),next=$('#activityNext');if(prev){prev.disabled=offset<=0;prev.onclick=()=>fetchActivity({offset:Math.max(0,offset-limit)})}if(next){next.disabled=offset+limit>=total;next.onclick=()=>fetchActivity({offset:offset+limit})}}
async function openActivityModal(){if($('#activityWrap'))return;document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="activityWrap"><div class="modal activity-modal"><div class="modal-head"><div><div class="detail-title" style="font-size:17px">Activity Log</div><div class="panel-sub">Search the permanent history of meaningful HSWare actions.</div></div><button class="btn icon-btn" id="activityClose" aria-label="Close">${icon('close')}</button></div><div class="activity-toolbar ${isAdmin()?'admin':''}"><div class="searchbar activity-search"><span class="search-icon">${icon('search')}</span><input class="input" id="activitySearch" placeholder="Search software, user, Package ID…"></div><select class="input activity-select" id="activityAction"><option value="">All actions</option></select>${isAdmin()?'<select class="input activity-select" id="activityUser"><option value="">All users</option></select>':''}<input class="input activity-date" id="activityFrom" type="date" aria-label="Activity from date"><input class="input activity-date" id="activityTo" type="date" aria-label="Activity to date"><button class="btn" id="activityApply">Apply</button></div><div class="activity-modal-list" id="activityResults"><div class="empty">Loading activity…</div></div><div class="activity-footer"><span class="helper" id="activityPageInfo"></span><div class="form-row"><button class="btn small" id="activityPrev">Previous</button><button class="btn small" id="activityNext">Next</button></div></div></div></div>`);$('#activityClose').onclick=()=>$('#activityWrap')?.remove();try{const d=await API('/api/activity?limit=40&offset=0');S.activityFilters=d.filters||{};$('#activityAction').innerHTML='<option value="">All actions</option>'+activityActionOptions(S.activityFilters);if($('#activityUser'))$('#activityUser').innerHTML='<option value="">All users</option>'+activityUserOptions(S.activityFilters);renderActivityModalResults(d,0);$('#activityApply').onclick=()=>fetchActivity({offset:0});$('#activitySearch').onkeydown=e=>{if(e.key==='Enter')fetchActivity({offset:0})}}catch(e){$('#activityResults').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
function softwarePanel(items,title,sub,actions=''){return`<section class="panel"><div class="panel-head"><div><div class="panel-title">${esc(title)} <span class="status draft">${items.length}</span></div><div class="panel-sub">${esc(sub)}</div></div><div class="form-row">${actions}<div class="searchbar"><span class="search-icon">${icon('search')}</span><input class="input" data-list-search placeholder="Search name, publisher, package ID…"></div></div></div><div class="list" data-list>${items.length?items.map(rowHtml).join(''):`<div class="empty">No software packages found.</div>`}</div></section>`}
function rowHtml(x){
  const installer=safeUrl(x.installerUrl);
  const source=safeUrl(x.sourcePageUrl);
  const android=isLiteApks(x);
  const sourceMeta=x.sourceMeta&&typeof x.sourceMeta==='object'?x.sourceMeta:{};
  const direct=safeUrl(sourceMeta.directDownloadUrl);
  const apkType=String(sourceMeta.apkType||sourceMeta.modInfo||'APK').trim()||'APK';
  const ready=x.enrichmentStatus==='ready'&&sourceReady(x);
  const fetching=x.enrichmentStatus==='fetching';
  const failed=x.enrichmentStatus==='error';
  const detailBadge=ready
    ? '<span class="status published">Details ready</span>'
    : fetching
      ? '<span class="status draft">Fetching details…</span>'
      : failed
        ? '<span class="status error">Fetch failed</span>'
        : '<span class="status draft">Details pending</span>';
  const claim=x.claim||null;
  const ownClaim=claim&&Number(claim.userId)===Number(S.data?.user?.id);
  const otherClaim=claim&&!ownClaim;
  const claimBadge=claim?`<span class="status ${ownClaim?'claim-own':'claim-other'}">${ownClaim?'Open · You':`Locked · ${esc(claim.name)}`}</span>`:'';
  return`<div class="software-row ${x.updateAvailable?'update':''} ${otherClaim?'locked':''}" data-row="${x.id}" data-search="${esc(`${x.name} ${x.publisher} ${x.packageId} ${x.sourcePackageId||''} ${x.category} ${platformLabel(x)}`.toLowerCase())}">
    <div class="sw-left">
      <div class="sw-info">
        <div class="sw-title-line">
          <button class="sw-name" data-open="${x.id}">${esc(x.name)}</button>
          <span class="status ${x.published?'published':'draft'}">${x.published?'Published':'Draft'}</span>
          ${detailBadge}
          ${android?'':`<span class="status quality">${Math.max(0,Math.min(100,Number(x.completeness||0)))}% Ready</span>`}
          ${claimBadge}
          ${x.updateAvailable?`<span class="status update">${android?'APK update available':`Update available: ${esc(x.latestVersion||'new version')}`}</span>`:''}
        </div>
        ${android
          ? `<div class="meta"><span class="status draft">Android APK</span><span>Version <b>${esc(x.version||'Pending')}</b></span><span>·</span><span>Size <b>${esc(bytes(x.fileSizeBytes))}</b></span><span>·</span><span>Requires <b>${esc(x.minimumOsVersion||'Android —')}</b></span><span>·</span><span><b>${esc(apkType)}</b></span></div>`
          : `<div class="meta"><span class="code">${esc(packageDisplay(x))}</span><span class="status published">Windows · WinGet</span><span>${esc(x.category||'Uncategorized')}</span><span>·</span><span>Version <b>${esc(x.version||'Pending')}</b></span><span>·</span><span>Publisher: <b>${esc(x.publisher||'—')}</b></span></div>`}
        ${android
          ? (direct?`<div class="linkline"><a href="${esc(direct)}" target="_blank" rel="noreferrer">${esc(direct)}</a><button class="btn small" data-copy="${esc(direct)}">Copy</button></div>`:(failed?`<div class="helper text-error">${esc(x.enrichmentError||'APK metadata could not be refreshed yet.')}</div>`:'<div class="helper">Direct APK link not exposed yet. Use refresh from details.</div>'))
          : installer
            ? `<div class="linkline"><a href="${esc(installer)}" target="_blank" rel="noreferrer">${esc(installer)}</a><button class="btn small" data-copy="${esc(installer)}">Copy</button></div>`
            : `<div class="helper ${failed?'text-error':''}">${failed?esc(x.enrichmentError||'Automatic enrichment could not fetch the current details yet.'):'Package metadata is still being refreshed.'}</div>`}
      </div>
    </div>
    <div class="sw-actions">
      <button class="btn small ${x.published?'':'success'}" data-publish="${x.id}" ${otherClaim?'disabled title="This software is being worked on by another user."':''}>${x.published?'Unpublish':'Publish'}</button>
      <button class="btn small open-btn" data-open="${x.id}">${otherClaim?'Locked':'Open'} ${icon('arrowRight')}</button>
    </div>
  </div>`
}
function bindSoftwareRows(root=document){root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(Number(b.dataset.open)));root.querySelectorAll('[data-publish]').forEach(b=>b.onclick=()=>togglePublish(Number(b.dataset.publish)));root.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{await copyText(b.dataset.copy)});const q=root.querySelector('[data-list-search]');if(q)q.oninput=()=>{const n=q.value.toLowerCase().trim();root.querySelectorAll('[data-row]').forEach(r=>r.style.display=!n||r.dataset.search.includes(n)?'':'none')}}
function claimKey(claim){return claim?`${Number(claim.userId)||0}|${claim.name||''}|${claim.role||''}`:''}
function updateSoftwareClaimInView(id,claim){id=Number(id);const item=S.softwareIndex.get(id)||S.software.find(x=>Number(x.id)===id);if(item)item.claim=claim||null;if(claim)S.activeClaims.set(id,claim);else S.activeClaims.delete(id);const row=document.querySelector(`[data-row="${id}"]`);if(!item||!row)return;const holder=document.createElement('template');holder.innerHTML=rowHtml(item).trim();const next=holder.content.firstElementChild;const parent=row.parentElement;row.replaceWith(next);if(parent)bindSoftwareRows(parent)}
async function syncWorkClaims(){try{const d=await API('/api/work-claims');const next=new Map((d.claims||[]).map(c=>[Number(c.softwareId),c]));const ids=new Set([...S.activeClaims.keys(),...next.keys()]);for(const id of ids){const before=S.activeClaims.get(id)||null;const after=next.get(id)||null;if(claimKey(before)!==claimKey(after))updateSoftwareClaimInView(id,after)}S.activeClaims=next}catch{}}
function startWorkClaimPoll(){if(S.claimPoll)clearInterval(S.claimPoll);S.claimPoll=setInterval(syncWorkClaims,5000)}
async function togglePublish(id){try{const item=S.softwareIndex.get(Number(id))||S.software.find(x=>Number(x.id)===Number(id));const android=isLiteApks(item);const d=await API(`/api/software/${id}/toggle-published`,{method:'POST',body:'{}'});toast(d.published?`Moved to ${android?'Published APK':'Published Software'}`:`Moved back to ${android?'New APK':'New Software'}`);await refreshBootstrap();await go(S.tab)}catch(e){if(e.status===423&&e.data?.claim)return showLockedSoftware(id,e.data.claim);toast(e.message)}}
function importedYear(x){const raw=x.importedAt||x.createdAt;if(!raw)return'';const d=new Date(raw);return Number.isNaN(d.getTime())?'':String(d.getFullYear())}
function newCategories(){return [...new Set(S.software.map(x=>x.category||'Uncategorized'))].sort((a,b)=>a.localeCompare(b))}
function filteredNewSoftware(){
  let items=[...S.software];
  if(S.newCategory!=='all')items=items.filter(x=>(x.category||'Uncategorized')===S.newCategory);
  const f=S.newFilter;
  if(/^year-/.test(f)){const y=f.slice(5);items=items.filter(x=>importedYear(x)===y)}
  else if(f==='ready')items=items.filter(x=>x.enrichmentStatus==='ready'&&sourceReady(x));
  else if(f==='pending')items=items.filter(x=>x.enrichmentStatus!=='ready'||!sourceReady(x));
  else if(f==='popular')items=items.filter(x=>x.priority!=null).sort((a,b)=>(a.priority??999999)-(b.priority??999999));
  else if(f==='most-popular')items=items.filter(x=>x.priority!=null&&Number(x.priority)<=100).sort((a,b)=>(a.priority??999999)-(b.priority??999999));
  else if(f==='high-demand')items=items.filter(x=>x.demandScore!=null).sort((a,b)=>(b.demandScore??-1)-(a.demandScore??-1));
  else items.sort((a,b)=>new Date(b.importedAt||b.createdAt||0)-new Date(a.importedAt||a.createdAt||0)||b.id-a.id);
  return items;
}
function newFilterBar(section){const android=section==='android';const categories=newCategories();const years=[...new Set(S.software.map(importedYear).filter(Boolean))].sort((a,b)=>b.localeCompare(a)).slice(0,8);const buttons=[['newest','Newest'],['popular','Popular First'],['most-popular','Top Ranked'],['high-demand','High Demand'],...years.map(y=>[`year-${y}`,y]),['ready','Details Ready'],['pending','Details Pending']];return`<section class="filter-panel"><div class="filter-title">${android?'New APK':'New Software'} Filters</div><div class="filter-row">${buttons.map(([v,l])=>`<button class="filter-chip ${S.newFilter===v?'active':''}" data-new-filter="${v}">${l}</button>`).join('')}<select class="input filter-select" id="newCategory"><option value="all">All categories</option>${categories.map(c=>`<option value="${esc(c)}" ${S.newCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div></section>`}
function bindNewFilters(root,section){root.querySelectorAll('[data-new-filter]').forEach(b=>b.onclick=()=>{S.newFilter=b.dataset.newFilter;renderNew(section)});const sel=$('#newCategory');if(sel)sel.onchange=()=>{S.newCategory=sel.value;renderNew(section)}}
function renderWorkspace(section){const view=workspaceView(section);if(view==='published')return renderPublished(section);if(view==='updates')return renderUpdates(section);return renderNew(section)}
function renderNew(section=currentWorkspace()||'desktop'){const android=section==='android';const c=$('#content');const items=filteredNewSoftware();const shown=items.slice(0,S.newLimit);const info=workspaceInfo(section);const adminAction=isAdmin()?`<button class="btn danger" id="clearNewSoftware">Clear ${android?'New APK':'New Software'}</button>`:'';c.innerHTML=workspaceTabs(section)+importPanel(section)+newFilterBar(section)+softwarePanel(shown,android?'New APK Queue':'New Software Queue',`${S.software.length} ${android?'APK':'software'} record(s) total · ${shown.length} currently rendered of ${items.length} matching.`,adminAction)+(items.length>S.newLimit?`<div style="text-align:center;margin:-8px 0 20px"><button class="btn" id="showMoreNew">Show ${fmt(Math.min(300,items.length-S.newLimit))} more</button></div>`:'');bindWorkspaceTabs(c,section);bindImport(c,section);bindNewFilters(c,section);bindSoftwareRows(c);if($('#clearNewSoftware'))$('#clearNewSoftware').onclick=()=>clearNewSoftware(section);const more=$('#showMoreNew');if(more)more.onclick=()=>{S.newLimit+=300;renderNew(section)};if(!android){const job=S.data?.importJob;if(job)showImportProgress(job);if(job&&['running','queued'].includes(job.status))pollImportState(++S.importPollToken)}}
function importPanel(section){const android=section==='android';const max=Number(S.data?.config?.autoImportMax||50000);const sync=S.data?.liteapksSync||{};const syncStatus=String(sync.status||'idle');if(android)return`<section class="panel"><div class="panel-head"><div><div class="panel-title">Smart APK Import</div><div class="panel-sub">Android records are sourced only from LiteAPKs and remain completely separate from Desktop Software.</div></div><div class="tabs"><button class="tab active" data-mode="auto">LiteAPKs Sync</button><button class="tab" data-mode="manual">Manual APK Import</button></div></div><div class="panel-body"><div id="autoMode"><div class="source-sync-card"><div><div style="font-size:15px;font-weight:700">Android · LiteAPKs daily catalog</div><div class="helper">Status: <b>${esc(syncStatus)}</b> · ${fmt(sync.processed_count||0)} / ${fmt(sync.total_count||0)} pages checked${sync.last_completed_at?` · last completed ${esc(relativeTime(sync.last_completed_at))}`:''}. Newly discovered app pages are added only to New APK.</div>${sync.last_error?`<div class="helper text-error">${esc(sync.last_error)}</div>`:''}</div>${isAdmin()?`<button class="btn primary" id="liteSync">Sync LiteAPKs Now</button>`:''}</div></div><div id="manualMode" style="display:none"><div class="form-row"><input id="manualQ" class="input wide" placeholder="App name or exact https://liteapks.com/...html URL"><button class="btn primary" id="manualSearch">Search</button></div><div class="helper" id="manualHint">Search the synced LiteAPKs catalog, or paste an exact LiteAPKs app page URL.</div><div id="manualResults" style="margin-top:14px"></div></div><div id="importMsg"></div></div></section>`;return`<section class="panel"><div class="panel-head"><div><div class="panel-title">Smart Software Import</div><div class="panel-sub">Desktop Software uses WinGet only. Android APK records cannot appear in this workspace.</div></div><div class="tabs"><button class="tab active" data-mode="auto">Auto Import</button><button class="tab" data-mode="manual">Manual Import</button></div></div><div class="panel-body"><div id="autoMode"><div style="font-size:15px;font-weight:700;margin-bottom:7px">Windows · WinGet bulk import</div><div class="form-row"><input id="autoCount" class="input import-count" type="number" min="1" max="${max}" placeholder="Number"><select id="autoInstallerFormat" class="input import-format" aria-label="Installer file type"><option value="all">All file types</option><option value="exe">EXE (.exe)</option><option value="msi">MSI (.msi)</option><option value="msix">MSIX (.msix / .msixbundle)</option><option value="appx">APPX (.appx / .appxbundle)</option><option value="portable">Portable / Archive</option></select><button class="btn primary" id="autoRun">Start WinGet Import</button><button class="btn" id="autoStop">Stop</button></div><div class="helper">This import writes only to Desktop Software.</div><div id="importProgress"></div></div><div id="manualMode" style="display:none"><div class="form-row"><input id="manualQ" class="input wide" placeholder="Software name or exact WinGet Package ID…"><button class="btn primary" id="manualSearch">Search</button></div><div class="helper" id="manualHint">Search WinGet by software name or exact Package ID.</div><div id="manualResults" style="margin-top:14px"></div></div><div id="importMsg"></div></div></section>`}
function bindImport(root,section){root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('#autoMode').style.display=b.dataset.mode==='auto'?'block':'none';$('#manualMode').style.display=b.dataset.mode==='manual'?'block':'none'});const run=$('#autoRun');if(run)run.onclick=runAutoImport;const stop=$('#autoStop');if(stop)stop.onclick=stopAutoImport;const search=$('#manualSearch');if(search)search.onclick=()=>manualSearch(section);const q=$('#manualQ');if(q)q.onkeydown=e=>{if(e.key==='Enter')manualSearch(section)};const sync=$('#liteSync');if(sync)sync.onclick=syncLiteApks}
async function runAutoImport(){const max=Number(S.data?.config?.autoImportMax||50000);const raw=String($('#autoCount').value||'').trim();const count=Math.floor(Number(raw));const installerFormat=String($('#autoInstallerFormat')?.value||'all');if(!raw||!Number.isFinite(count)||count<1||count>max){$('#importMsg').innerHTML=`<div class="notice error">Enter a number from 1 to ${fmt(max)}.</div>`;$('#autoCount').focus();return}const btn=$('#autoRun');btn.disabled=true;try{const d=await API('/api/import/auto/start',{method:'POST',body:JSON.stringify({count,installerFormat})});S.data.importJob=d.job;showImportProgress(d.job);$('#importMsg').innerHTML=`<div class="notice"><b>Import started.</b> HSWare will import only qualified Windows packages matching <b>${esc((d.job?.installer_format||installerFormat).toUpperCase())}</b>${installerFormat==='all'?' file selection.':' installers.'} It continues on the server if you close this tab.</div>`;pollImportState(++S.importPollToken)}catch(e){$('#importMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{btn.disabled=false}}
function showImportProgress(j){if(!j||!$('#importProgress'))return;const processed=Number(j.completed_count||0)+Number(j.failed_count||0);const requested=Math.max(1,Number(j.requested_count||1));const finished=!['running','queued'].includes(j.status);const pct=finished?100:Math.min(99.5,processed/requested*100);const phase={discovering:'Discovering more WinGet packages…',importing:'Verifying and importing…',target_reached:'Target reached',source_exhausted:'WinGet source exhausted',stopped:'Stopped'}[j.phase]||j.status;const format=String(j.installer_format||'all').toUpperCase();$('#importProgress').innerHTML=`<div class="progress"><span style="width:${pct}%"></span></div><div class="helper"><b>${esc(phase)}</b> · ${fmt(j.completed_count)} imported · ${fmt(j.failed_count)} rejected/failed · target ${fmt(j.requested_count)} · file type ${esc(format)}${Number(j.available_count||0)?` · ${fmt(j.available_count)} discovered`:''}${j.current_package?` · checking ${esc(j.current_package)}`:''}</div>${j.phase==='source_exhausted'?'<div class="notice amber" style="margin-top:10px;margin-bottom:0">The requested target is larger than the eligible WinGet packages currently available. HSWare imported everything it could discover instead of inventing extra entries.</div>':''}`;const run=$('#autoRun'),stop=$('#autoStop');if(run)run.disabled=!finished;if(stop)stop.disabled=finished}
async function stopAutoImport(){try{const d=await API('/api/import/auto/stop',{method:'POST',body:'{}'});S.data.importJob=d.job;S.importPollToken++;showImportProgress(d.job);$('#importMsg').innerHTML='<div class="notice">Bulk import stopped. Already imported software remains in Desktop → New Software.</div>';await refreshBootstrap()}catch(e){toast(e.message)}}
async function pollImportState(token){let lastCompleted=Number(S.data?.importJob?.completed_count||0);while(token===S.importPollToken&&S.tab==='desktop'&&workspaceView('desktop')==='new'){await delay(2500);if(token!==S.importPollToken||S.tab!=='desktop'||workspaceView('desktop')!=='new')return;try{const d=await API('/api/import/auto/state');if(!d.job)return;S.data.importJob=d.job;showImportProgress(d.job);const completed=Number(d.job.completed_count||0);if(completed-lastCompleted>=25){lastCompleted=completed;await refreshBootstrap()}if(!['running','queued'].includes(d.job.status)){await refreshBootstrap();await loadSoftware('unpublished','windows');renderNew('desktop');const msg=$('#importMsg');if(msg)msg.innerHTML=`<div class="notice"><b>Bulk import finished.</b> ${fmt(d.job.completed_count)} Windows software packages were added · ${fmt(d.job.failed_count)} rejected/failed.</div>`;return}}catch(e){const msg=$('#importMsg');if(msg)msg.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;return}}}
async function manualSearch(section=currentWorkspace()||'desktop'){const q=$('#manualQ').value.trim();if(!q)return;const source=section==='android'?'liteapks':'winget';if(source==='liteapks'&&/^https?:\/\/(?:www\.)?liteapks\.com\/.+\.html(?:[?#].*)?$/i.test(q)){const url=safeUrl(q);$('#manualResults').innerHTML=`<div class="manual-results"><article class="manual-result-card"><div class="manual-result-content"><div class="manual-result-name">LiteAPKs Android app page</div><div class="manual-result-meta"><span class="manual-package-id">${esc(url)}</span></div></div><div class="manual-result-action"><button class="btn small primary manual-action-btn" data-lite-url="${esc(url)}">${icon('plus')} Add + Open</button></div></article></div>`;$('#manualResults').querySelector('[data-lite-url]').onclick=b=>manualImport('',b.currentTarget.dataset.liteUrl,'liteapks');return}$('#manualResults').innerHTML=`<div class="notice">Searching ${source==='liteapks'?'the synced LiteAPKs Android catalog':'HSWare and WinGet candidates'}…</div>`;try{const d=await API(`/api/import/manual/search?q=${encodeURIComponent(q)}&source=${encodeURIComponent(source)}`);$('#manualResults').innerHTML=d.results.length?`<div class="manual-results">${d.results.map(r=>`<article class="manual-result-card"><div class="manual-result-content"><div class="manual-result-name">${esc(r.name)}</div><div class="manual-result-meta"><span class="manual-package-id">${esc(r.sourcePackageId||r.packageId)}</span><span class="manual-meta-dot">•</span><span>${esc(r.publisher||'Unknown publisher')}</span><span class="manual-meta-dot">•</span><span>${esc(r.category||'Uncategorized')}</span></div></div><div class="manual-result-action">${r.managed?`<button class="btn small manual-action-btn" data-open-managed="${r.managedSoftwareId}">Open ${icon('arrowRight')}</button>`:`<button class="btn small primary manual-action-btn" data-import="${esc(r.packageId)}" data-source="${esc(r.sourceType||source)}" data-source-url="${esc(r.sourcePageUrl||'')}">${icon('plus')} Add + Open</button>`}</div></article>`).join('')}</div>`:`<div class="notice amber">No match found.${source==='liteapks'?' Run the LiteAPKs sync or paste an exact LiteAPKs app-page URL.':' You can enter an exact WinGet Package ID such as VideoLAN.VLC.'}</div>`;$('#manualResults').querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>manualImport(b.dataset.import,b.dataset.sourceUrl,b.dataset.source));$('#manualResults').querySelectorAll('[data-open-managed]').forEach(b=>b.onclick=()=>openDetail(Number(b.dataset.openManaged)))}catch(e){$('#manualResults').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function manualImport(packageId,sourcePageUrl='',sourceType='winget'){const android=String(sourceType)==='liteapks';$('#importMsg').innerHTML=`<div class="notice">${android?'Reading LiteAPKs app metadata':'Verifying with WinGet'} before adding it…</div>`;try{const d=await API('/api/import/manual',{method:'POST',body:JSON.stringify({packageId,sourcePageUrl,sourceType})});toast(android?'Android APK record added':'Verified desktop software added');await refreshBootstrap();await go(android?'android':'desktop','new');await openDetail(Number(d.id))}catch(e){$('#importMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function syncLiteApks(){const btn=$('#liteSync');if(btn)btn.disabled=true;try{const d=await API('/api/liteapks/sync',{method:'POST',body:JSON.stringify({mode:'auto'})});S.data.liteapksSync=d.state;toast('LiteAPKs Android sync started');renderNew('android')}catch(e){toast(e.message,'error')}finally{if(btn&&document.body.contains(btn))btn.disabled=false}}
async function clearNewSoftware(section=currentWorkspace()||'desktop'){const android=section==='android';const label=android?'New APK':'New Software';if(!confirm(`Clear every unpublished item from ${label}? The other workspace and all published records will not be changed.`))return;try{const d=await API('/api/workspace/clear-new',{method:'POST',body:JSON.stringify({platform:android?'android':'windows'})});toast(`${fmt(d.cleared||0)} ${label} item(s) cleared`);await refreshBootstrap();await go(section,'new')}catch(e){toast(e.message)}}
function publishedYear(x){const raw=x.publishedAt||x.importedAt||x.createdAt;if(!raw)return'';const d=new Date(raw);return Number.isNaN(d.getTime())?'':String(d.getFullYear())}
function publishedCategories(){return [...new Set(S.software.map(x=>x.category||'Uncategorized'))].sort((a,b)=>a.localeCompare(b))}
function filteredPublishedSoftware(){
  let items=[...S.software];
  if(S.publishedCategory!=='all')items=items.filter(x=>(x.category||'Uncategorized')===S.publishedCategory);
  const f=S.publishedFilter;
  if(/^year-/.test(f)){const y=f.slice(5);items=items.filter(x=>publishedYear(x)===y)}
  else if(f==='updates')items=items.filter(x=>x.updateAvailable);
  else if(f==='popular')items=items.filter(x=>x.priority!=null).sort((a,b)=>(a.priority??999999)-(b.priority??999999));
  else if(f==='most-popular')items=items.filter(x=>x.priority!=null&&Number(x.priority)<=100).sort((a,b)=>(a.priority??999999)-(b.priority??999999));
  else if(f==='high-demand')items=items.filter(x=>x.demandScore!=null).sort((a,b)=>(b.demandScore??-1)-(a.demandScore??-1));
  else items.sort((a,b)=>new Date(b.publishedAt||b.importedAt||b.createdAt||0)-new Date(a.publishedAt||a.importedAt||a.createdAt||0)||b.id-a.id);
  return items;
}
function publishedFilterBar(section){const android=section==='android';const categories=publishedCategories();const years=[...new Set(S.software.map(publishedYear).filter(Boolean))].sort((a,b)=>b.localeCompare(a)).slice(0,8);const buttons=[['newest','Newest'],['popular','Popular First'],['most-popular','Top Ranked'],['high-demand','High Demand'],['updates','Update Available'],...years.map(y=>[`year-${y}`,y])];return`<section class="filter-panel"><div class="filter-title">${android?'Published APK':'Published Software'} Filters</div><div class="filter-row">${buttons.map(([v,l])=>`<button class="filter-chip ${S.publishedFilter===v?'active':''}" data-published-filter="${v}">${l}</button>`).join('')}<select class="input filter-select" id="publishedCategory"><option value="all">All categories</option>${categories.map(c=>`<option value="${esc(c)}" ${S.publishedCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div></section>`}
function bindPublishedFilters(root,section){root.querySelectorAll('[data-published-filter]').forEach(b=>b.onclick=()=>{S.publishedFilter=b.dataset.publishedFilter;renderPublished(section)});const sel=$('#publishedCategory');if(sel)sel.onchange=()=>{S.publishedCategory=sel.value;renderPublished(section)}}
function renderPublished(section=currentWorkspace()||'desktop'){const android=section==='android';const c=$('#content');const items=filteredPublishedSoftware();const shown=items.slice(0,S.publishedLimit);c.innerHTML=workspaceTabs(section)+publishedFilterBar(section)+softwarePanel(shown,android?'Published APK':'Published Software',`${shown.length} currently rendered of ${items.length} matching · ${android?'Android APK':'Desktop software'} library only.`)+(items.length>S.publishedLimit?`<div style="text-align:center;margin:-8px 0 20px"><button class="btn" id="showMorePublished">Show ${fmt(Math.min(300,items.length-S.publishedLimit))} more</button></div>`:'');bindWorkspaceTabs(c,section);bindPublishedFilters(c,section);bindSoftwareRows(c);const more=$('#showMorePublished');if(more)more.onclick=()=>{S.publishedLimit+=300;renderPublished(section)}}
function renderUpdates(section=currentWorkspace()||'desktop'){const android=section==='android';const c=$('#content');c.innerHTML=workspaceTabs(section)+`<section class="panel"><div class="panel-head"><div><div class="panel-title">${android?'APK Update Engine':'Software Update Engine'}</div><div class="panel-sub">${android?'Check Android APK records against the current Android source metadata only.':'Check Desktop Software against WinGet only.'}</div></div><button class="btn primary" id="scanUpdates">${icon('refresh')} ${android?'Check APK Updates':'Check Software Updates'}</button></div><div class="panel-body" id="updateProgress"><div class="helper">Only ${android?'Android APK':'Desktop Software'} records are included in this scan.</div></div></section>`+softwarePanel(S.software,android?'APK Updates':'Software Updates',`Open an update to review the latest ${android?'Android APK':'WinGet'} metadata and version.`);bindWorkspaceTabs(c,section);$('#scanUpdates').onclick=()=>scanUpdates(section);bindSoftwareRows(c)}
async function scanUpdates(section=currentWorkspace()||'desktop'){const android=section==='android';const platform=android?'android':'windows';const btn=$('#scanUpdates');btn.disabled=true;try{let d=await API('/api/updates/start',{method:'POST',body:JSON.stringify({platform})});while(d.state?.status==='running'){showUpdateProgress(d.state);d=await API('/api/updates/step',{method:'POST',body:JSON.stringify({platform})});if(d.state.status!=='running')break;await delay(100)}showUpdateProgress(d.state);toast(`${d.state.update_count||0} ${android?'APK':'software'} update(s) found`);await refreshBootstrap();await go(section,'updates')}catch(e){$('#updateProgress').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{if(document.body.contains(btn))btn.disabled=false}}
function showUpdateProgress(s){const pct=Number(s.total_count)?Number(s.processed_count)/Number(s.total_count)*100:0;$('#updateProgress').innerHTML=`<div class="progress"><span style="width:${pct}%"></span></div><div class="helper">${fmt(s.processed_count)} / ${fmt(s.total_count)} checked · ${fmt(s.update_count)} update(s) · ${fmt(s.failed_count)} failed</div>`}
async function loadUsers(){if(!isAdmin())return[];const d=await API('/api/users');S.users=d.users||[];return S.users}
function teamUserCard(u,{self=false}={}){return`<div class="team-user ${u.active?'':'disabled'}"><div class="team-user-main">${avatarHtml(u,'team-avatar')}<div class="team-user-copy"><div class="team-name-line"><b>${esc(u.name||'Unnamed user')}</b><span class="status ${u.role==='admin'?'quality':'draft'}">${esc(u.roleLabel||u.role)}</span>${u.active?'<span class="status published">Active</span>':'<span class="status error">Disabled</span>'}</div><div class="team-email">${esc(u.email)}</div>${u.lastLoginAt?`<div class="team-last">Last login ${esc(dateTimeLabel(u.lastLoginAt))}</div>`:''}</div></div><div class="team-user-actions"><button class="btn small" data-edit-user="${u.id}" data-self="${self?'1':'0'}">Edit</button>${u.role==='partner'?`<button class="btn small ${u.active?'danger':''}" data-user-status="${u.id}" data-active="${u.active?'0':'1'}">${u.active?'Disable':'Enable'}</button>`:''}</div></div>`}
function renderSettings(){if(!isAdmin())return go('dashboard');const d=S.data.config||{},b=S.data.backup||{},last=b.last;const admin=S.users.find(u=>u.role==='admin')||S.data.user;const partners=S.users.filter(u=>u.role==='partner');$('#content').innerHTML=`<div style="margin-bottom:18px"><div class="panel-title">Settings</div><div class="panel-sub">Team access, workspace backup and deployment controls.</div></div><section class="setting-card team-access-card"><div class="team-head"><div><div class="setting-title">Team & Access</div><div class="setting-value">Admin + Partners</div><div class="helper">The Admin controls HSWare. Partners can import, review, publish and update software but cannot access Settings, Database Health, backups, restore, reset, or force controls.</div></div><button class="btn primary" id="addPartner">${icon('plus')} Add Partner</button></div><div class="team-section-label">Your Account</div>${teamUserCard(admin,{self:true})}<div class="team-section-label partners-label">Partners <span class="badge">${fmt(partners.length)}</span></div><div class="team-list">${partners.length?partners.map(u=>teamUserCard(u)).join(''):'<div class="team-empty">No Partner accounts yet. Add a Partner to give another person their own HSWare login.</div>'}</div></section><div class="settings-grid"><div class="setting-card"><div class="setting-title">Database</div><div class="setting-value">${esc(d.dbName||'Configured')}</div><div class="helper">Stores separated Desktop Software and Android APK queues, published libraries, version history, metadata, user access and work claims.</div></div><div class="setting-card"><div class="setting-title">GitHub API Token</div><div class="setting-value">${d.githubConfigured?'Configured':'Not configured'}</div><div class="helper">${d.githubConfigured?'Authenticated GitHub access is active.':'Recommended for large Windows/WinGet discovery. LiteAPKs Android sync is independent of GitHub.'}</div></div><div class="setting-card"><div class="setting-title">Bulk Import</div><div class="setting-value">Up to ${fmt(d.autoImportMax||50000)}</div><div class="helper">Admin and Partner accounts can use both Auto Import and Manual Import.</div></div><div class="setting-card"><div class="setting-title">Environment</div><div class="setting-value">${esc(d.nodeEnv||'production')}</div><div class="helper">HSWare Studio v4.6.0 · Astro 7 + Express · separated Desktop Software and Android APK workspaces.</div></div><div class="setting-card backup-card" style="grid-column:1/-1"><div class="setting-title">Backup & Restore</div><div class="backup-status-row"><div><div class="setting-value">Automatic JSON backup every 24 hours</div><div class="helper">Last backup: <b>${esc(dateTimeLabel(last?.createdAt))}</b>${last?.fileSizeBytes?` · ${bytes(last.fileSizeBytes)}`:''}. Backups contain workspace software and version data, not user passwords or environment secrets.</div></div><span class="status ${b.unreadAutomatic?'update':'published'}">${b.unreadAutomatic?'Ready to download':'Backup active'}</span></div><div class="backup-actions"><button class="btn primary" id="createBackup">Create Backup Now</button>${last?.id&&last?.exists?`<button class="btn" id="downloadLatestBackup">Download Latest JSON</button>`:''}<label class="btn backup-file-label" for="restoreBackupFile">Choose JSON Backup</label><input id="restoreBackupFile" type="file" accept=".json,application/json" hidden><button class="btn danger" id="restoreBackup" disabled>Upload & Restore</button></div><div class="helper" id="backupFileName">No restore file selected.</div><div id="backupMsg"></div></div><div class="setting-card" style="grid-column:1/-1"><div class="setting-title">Data Reset</div><div class="helper">Clears software workspace data. Admin and Partner login accounts are kept.</div><div style="margin-top:12px"><button class="btn danger" id="resetAllData">Reset All Software Data</button></div></div></div>`;
  $('#addPartner').onclick=()=>openUserModal();
  document.querySelectorAll('[data-edit-user]').forEach(btn=>btn.onclick=()=>{const u=S.users.find(x=>Number(x.id)===Number(btn.dataset.editUser));if(u)openUserModal(u,btn.dataset.self==='1')});
  document.querySelectorAll('[data-user-status]').forEach(btn=>btn.onclick=()=>togglePartnerStatus(Number(btn.dataset.userStatus),btn.dataset.active==='1'));
  $('#createBackup').onclick=createManualBackup;const dl=$('#downloadLatestBackup');if(dl)dl.onclick=()=>downloadBackup(last.id);const file=$('#restoreBackupFile');const restore=$('#restoreBackup');file.onchange=()=>{const chosen=file.files?.[0];$('#backupFileName').textContent=chosen?chosen.name:'No restore file selected.';restore.disabled=!chosen};restore.onclick=restoreFromBackup;$('#resetAllData').onclick=async()=>{const v=prompt('Type RESET to permanently clear all HSWare software data.');if(v!=='RESET')return;try{await API('/api/maintenance/reset-all',{method:'POST',body:JSON.stringify({confirm:v})});toast('All HSWare software data cleared');await refreshBootstrap();await go('dashboard')}catch(e){toast(e.message)}}
}
function openUserModal(user=null,self=false){
  const editing=Boolean(user),role=self?'Admin':'Partner';let previewUrl=null,createdUser=null;
  document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="userModal"><div class="modal user-modal"><div class="modal-head"><div><div class="detail-title" style="font-size:17px">${self?'Edit Your Account':editing?'Edit Partner':'Add Partner'}</div><div class="panel-sub">${self?'Update the Admin profile and login details.':'Partner accounts use the same HSWare sign-in page.'}</div></div><button class="btn icon-btn" id="userModalClose" aria-label="Close">${icon('close')}</button></div><div class="panel-body"><div class="user-form-profile"><div id="userAvatarPreview">${avatarHtml(user||{name:''},'user-form-avatar')}</div><div><label class="btn small" for="userAvatarFile">Choose Profile Photo</label><input id="userAvatarFile" type="file" accept="image/jpeg,image/png,image/webp" hidden><div class="helper">JPG, PNG or WEBP · maximum 2 MB.</div>${editing&&user?.hasAvatar?'<button class="link-button danger-text" id="removeUserAvatar" type="button">Remove current photo</button>':''}</div></div><form id="userForm" class="user-form"><label>Full Name<input class="input" id="userName" maxlength="120" required value="${esc(user?.name||'')}"></label><label>Email<input class="input" id="userEmail" type="email" maxlength="190" required value="${esc(user?.email||'')}"></label><div class="user-role-readonly"><span>Role</span><b>${esc(role)}</b></div><label>${editing?'New Password <span class="optional">Optional</span>':'Password'}<input class="input" id="userPassword" type="password" minlength="10" maxlength="200" ${editing?'':'required'} autocomplete="new-password" placeholder="${editing?'Leave blank to keep current password':'At least 10 characters'}"></label><label>${editing?'Confirm New Password':'Confirm Password'}<input class="input" id="userPassword2" type="password" minlength="10" maxlength="200" ${editing?'':'required'} autocomplete="new-password"></label><div id="userFormMsg"></div><div class="user-form-actions"><button class="btn" type="button" id="userCancel">Cancel</button><button class="btn primary" type="submit" id="userSave">${editing?'Save Changes':'Add Partner'}</button></div></form></div></div></div>`);
  const cleanup=()=>{if(previewUrl)URL.revokeObjectURL(previewUrl);$('#userModal')?.remove()};
  $('#userModalClose').onclick=cleanup;$('#userCancel').onclick=cleanup;const file=$('#userAvatarFile');
  file.onchange=()=>{const chosen=file.files?.[0];if(!chosen)return;if(!['image/jpeg','image/png','image/webp'].includes(chosen.type)){const msg=$('#userFormMsg');if(msg)msg.innerHTML='<div class="notice error">Choose a JPG, PNG or WEBP profile photo.</div>';file.value='';return}if(chosen.size>2*1024*1024){const msg=$('#userFormMsg');if(msg)msg.innerHTML='<div class="notice error">Profile photo must be 2 MB or smaller.</div>';file.value='';return}if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(chosen);$('#userAvatarPreview').innerHTML=`<img class="user-form-avatar" src="${esc(previewUrl)}" alt="Profile preview">`};
  if($('#removeUserAvatar'))$('#removeUserAvatar').onclick=async()=>{try{const d=await API(`/api/users/${user.id}/avatar`,{method:'DELETE',body:'{}'});Object.assign(user,d.user||{hasAvatar:false,avatarUrl:null});$('#userAvatarPreview').innerHTML=avatarHtml(user,'user-form-avatar');$('#removeUserAvatar').remove();if(self)await refreshBootstrap();await loadUsers();toast('Profile photo removed')}catch(e){$('#userFormMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}};
  $('#userForm').onsubmit=async e=>{e.preventDefault();const name=$('#userName').value.trim(),email=$('#userEmail').value.trim(),password=$('#userPassword').value,password2=$('#userPassword2').value;if(password!==password2){$('#userFormMsg').innerHTML='<div class="notice error">Passwords do not match.</div>';return}const save=$('#userSave');save.disabled=true;$('#userFormMsg').innerHTML='';try{let result;if(self)result=await API('/api/account',{method:'PATCH',body:JSON.stringify({name,email,password})});else if(editing)result=await API(`/api/users/${user.id}`,{method:'PATCH',body:JSON.stringify({name,email,password})});else{result=await API('/api/users',{method:'POST',body:JSON.stringify({name,email,password})});createdUser=result.user}const target=result.user;let photoWarning='';if(file.files?.[0]){const image=file.files[0];try{result=await API(`/api/users/${target.id}/avatar`,{method:'PUT',headers:{'content-type':image.type},body:image})}catch(photoErr){photoWarning=` Profile photo was not saved: ${photoErr.message}`}}if(self)await refreshBootstrap();await loadUsers();cleanup();renderSettings();toast(`${self?'Admin account updated':editing?'Partner updated':'Partner added'}.${photoWarning}`.trim())}catch(err){if(createdUser){await loadUsers();cleanup();renderSettings();toast(`Partner account was created, but the remaining update failed: ${err.message}`);return}$('#userFormMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;save.disabled=false}}
}
async function togglePartnerStatus(id,active){const user=S.users.find(u=>Number(u.id)===Number(id));const verb=active?'enable':'disable';if(!confirm(`${verb[0].toUpperCase()+verb.slice(1)} ${user?.name||'this Partner'}?`))return;try{await API(`/api/users/${id}/status`,{method:'POST',body:JSON.stringify({active})});await loadUsers();renderSettings();toast(`Partner ${active?'enabled':'disabled'}`)}catch(e){toast(e.message)}}
async function refreshBackupState(){try{const d=await API('/api/backups/state');S.data.backup=d.backup;return d.backup}catch{return S.data.backup}}
function startBackupNotificationPoll(){const timer=setInterval(async()=>{if(!S.data)return;const before=Boolean(S.data.backup?.unreadAutomatic);const current=await refreshBackupState();if(current?.unreadAutomatic&&!before)showBackupNotification()},60000);return timer}
function downloadBackup(id){if(!id)return;window.location.href=`/api/backups/${encodeURIComponent(id)}/download`;if(S.data?.backup){S.data.backup.unreadAutomatic=false;if(S.data.backup.lastAuto)S.data.backup.lastAuto.downloadedAt=new Date().toISOString()}document.querySelector('.backup-alert')?.remove()}
function showBackupNotification(){const b=S.data?.backup;if(!b?.unreadAutomatic||!b.lastAuto?.id||document.querySelector('.backup-alert'))return;const box=document.createElement('div');box.className='backup-alert';box.innerHTML=`<div><b>Daily backup created</b><span>Your HSWare JSON backup is ready to download.</span></div><div class="backup-alert-actions"><button class="btn small" id="backupAlertDownload">Download JSON</button><button class="backup-alert-close" id="backupAlertClose" aria-label="Close">${icon('close')}</button></div>`;document.body.appendChild(box);$('#backupAlertDownload').onclick=()=>downloadBackup(b.lastAuto.id);$('#backupAlertClose').onclick=()=>box.remove()}
async function createManualBackup(){const btn=$('#createBackup');btn.disabled=true;try{const d=await API('/api/backups/create',{method:'POST',body:'{}'});S.data.backup=d.state;toast('JSON backup created');renderSettings()}catch(e){$('#backupMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{if(document.body.contains(btn))btn.disabled=false}}
async function restoreFromBackup(){const file=$('#restoreBackupFile')?.files?.[0];if(!file)return;if(!confirm('Restore this HSWare backup? Current software data will be replaced. HSWare creates a safety backup first.'))return;const btn=$('#restoreBackup');btn.disabled=true;$('#backupMsg').innerHTML='<div class="notice">Validating and restoring backup…</div>';try{const data=await API('/api/backups/restore',{method:'POST',headers:{'content-type':'application/octet-stream'},body:file});toast(`Restored ${fmt(data.restoredSoftware)} software records`);await refreshBootstrap();await go('dashboard')}catch(e){$('#backupMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`;btn.disabled=false}}
async function pollDetail(id,token,attempt=0){
  if(attempt>=10||token!==S.detailPollToken||!$('#modalWrap')||S.detail?.id!==id)return;
  if(S.detail.enrichmentStatus==='ready'&&enrichedRevision(S.detail))return;
  await delay(3000);
  if(token!==S.detailPollToken||!$('#modalWrap')||S.detail?.id!==id)return;
  try{const d=await API(`/api/software/${id}`);S.detail=d.software;renderDetail()}catch{}
  pollDetail(id,token,attempt+1);
}
function stopDetailHeartbeat(){if(S.detailHeartbeat){clearInterval(S.detailHeartbeat);S.detailHeartbeat=null}}
function startDetailHeartbeat(id){stopDetailHeartbeat();S.detailHeartbeat=setInterval(async()=>{if(!$('#modalWrap')||S.detail?.id!==id)return stopDetailHeartbeat();try{await API(`/api/software/${id}/heartbeat`,{method:'POST',body:'{}'})}catch(e){if(e.status===423&&e.data?.claim){stopDetailHeartbeat();updateSoftwareClaimInView(id,e.data.claim);showLockedSoftware(id,e.data.claim);return}if(e.status===409){stopDetailHeartbeat();updateSoftwareClaimInView(id,null);toast('Your work claim was released. Reopen the software to continue.');closeDetail()}}},30000)}
function showLockedSoftware(id,claim){stopDetailHeartbeat();S.detailPollToken++;S.detail=null;updateSoftwareClaimInView(id,claim||null);if(!$('#modalWrap'))document.body.insertAdjacentHTML('beforeend','<div class="modal-wrap" id="modalWrap"></div>');const admin=isAdmin();$('#modalWrap').innerHTML=`<div class="modal lock-modal"><div class="modal-head"><div><div class="detail-title" style="font-size:17px">Software is currently open</div><div class="panel-sub">HSWare allows only one person to keep this software open at a time.</div></div><button class="btn icon-btn" id="closeModal" aria-label="Close">${icon('close')}</button></div><div class="panel-body"><div class="lock-owner"><div class="lock-icon">${icon('check')}</div><div><div class="lock-owner-name">${esc(claim?.name||'Another user')}</div><div class="helper">${esc(claim?.roleLabel||'Partner')} · opened ${claim?.claimedAt?esc(dateTimeLabel(claim.claimedAt)):'recently'}</div></div></div><div class="notice amber">The lock is temporary. It is released automatically when the owner closes the software window, publishes it, signs out, or stops sending a heartbeat.</div><div class="lock-actions"><button class="btn" id="lockBack">Back</button>${admin?'<button class="btn danger" id="forceRelease">Force Release</button><button class="btn primary" id="takeOver">Take Over</button>':''}</div></div></div>`;$('#closeModal').onclick=closeDetail;$('#lockBack').onclick=closeDetail;if(admin){$('#forceRelease').onclick=async()=>{try{await API(`/api/software/${id}/release`,{method:'POST',body:JSON.stringify({force:true})});toast('Work lock released');closeDetail();await go(S.tab)}catch(e){toast(e.message)}};$('#takeOver').onclick=async()=>{try{await API(`/api/software/${id}/takeover`,{method:'POST',body:'{}'});toast('Software taken over');await openDetail(id)}catch(e){toast(e.message)}}}}
async function openDetail(id){
  id=Number(id);
  if(S.releasePromises.has(id))await S.releasePromises.get(id);
  if(!$('#modalWrap'))document.body.insertAdjacentHTML('beforeend','<div class="modal-wrap" id="modalWrap"><div class="modal"><div class="empty">Opening software workspace…</div></div></div>');
  try{const claim=await API(`/api/software/${id}/claim`,{method:'POST',body:'{}'});updateSoftwareClaimInView(id,claim.claim||null);const d=await API(`/api/software/${id}`);S.detail=d.software;S.detail.claim=claim.claim||S.detail.claim;renderDetail();startDetailHeartbeat(id);const token=++S.detailPollToken;pollDetail(id,token)}
  catch(e){if(e.status===423&&e.data?.claim)return showLockedSoftware(id,e.data.claim);$('#modalWrap').innerHTML=`<div class="modal"><div class="panel-body"><div class="notice error">${esc(e.message)}</div><button class="btn" id="closeModal">Close</button></div></div>`;$('#closeModal').onclick=closeDetail}
}
async function closeDetail({release=true}={}){const x=S.detail;stopDetailHeartbeat();S.detailPollToken++;$('#modalWrap')?.remove();S.detail=null;if(release&&x?.id){const id=Number(x.id);const pending=API(`/api/software/${id}/release`,{method:'POST',body:'{}'}).then(()=>updateSoftwareClaimInView(id,null)).catch(()=>{}).finally(()=>S.releasePromises.delete(id));S.releasePromises.set(id,pending);await pending}}
function releaseDetailOnPageExit(){const x=S.detail;if(!x?.id||!S.csrf)return;fetch(`/api/software/${x.id}/release`,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-csrf-token':S.csrf},body:'{}',keepalive:true}).catch(()=>{})}
function field(label,value,copy='',meta=''){
  const chip=meta?`<span class="field-meta ${meta==='Auto'?'auto':''}">${esc(meta)}</span>`:'';
  return`<div class="field"><div class="field-label-row"><div class="field-label">${esc(label)}</div>${chip}</div><div class="field-value">${value||'N/A'}${copy?` <button class="btn tiny" data-copy="${esc(copy)}">Copy</button>`:''}</div></div>`
}
function allDetailsText(x){
  const android=isLiteApks(x);
  const lines=[];
  const add=(label,value)=>lines.push(`${label}: ${value||'N/A'}`);
  if(android){
    const meta=x.sourceMeta&&typeof x.sourceMeta==='object'?x.sourceMeta:{};
    add('App Name',x.name);
    add('Version',x.version);
    add('App Size',bytes(x.fileSizeBytes));
    add('Requires Android',x.minimumOsVersion||'Not reported');
    add('APK License / Type',meta.apkType||meta.modInfo||'APK');
    add('User Rating',meta.ratingValue==null?'Not reported':`${meta.ratingValue}/5`);
    add('Downloads',x.downloadCount==null?'Not reported':count(x.downloadCount));
    add('Original Play Store Link',safeUrl(meta.playStoreUrl)||'Not available');
    add('Direct Download Link',safeUrl(meta.directDownloadUrl)||'Resolver pending');
    add('Icon',meta.iconUrl?'Available for download':'Not reported');
    add('Screenshots',Array.isArray(meta.screenshots)?`${meta.screenshots.length} available`:'Not reported');
    return lines.join('\n');
  }
  add('Software Name',x.name);add('Developer',x.developer);add('Publisher',x.publisher);add('Category',x.category);add('WinGet Package ID',packageDisplay(x));add('Current Version',x.version);add('File Size',bytes(x.fileSizeBytes));add('License',x.licenseName||'N/A');add('Language',x.language||'English');add('Platform',platformLabel(x));add('Minimum OS Version',osLabel(x.minimumOsVersion));add('Processor',processorLabel(x));add('RAM',requirementValue(x,x.ramRequirement));add('Storage',storageLabel(x.storageRequirement));add('Graphic Card',requirementValue(x,x.graphicsRequirement));add('Architecture',x.architecture);add('Installer Type',x.installerType);add('Official Website',safeUrl(x.officialUrl));add('Direct Download Link',safeUrl(x.installerUrl));add('SHA-256',x.sha256);
  lines.push('', 'Description:', x.description||'N/A', '', 'Previous Versions:');
  if(x.versions?.length){x.versions.slice(0,5).forEach((v,i)=>{lines.push(`${i+1}. Version: ${v.version||'Unknown'}`);lines.push(`   Download Link: ${safeUrl(v.installerUrl)||'N/A'}`);lines.push(`   Updated: ${dateLabel(v.updatedDate)}`)})}else lines.push('No older WinGet version available.');
  lines.push('',`Last Metadata Refresh: ${x.enrichedAt||'N/A'}`,'Source: Microsoft WinGet + verified official pages; Auto values are HSWare fallbacks when an official minimum is unavailable.');
  return lines.join('\n');
}

function renderAndroidDetail(x){
  const meta=x.sourceMeta&&typeof x.sourceMeta==='object'?x.sourceMeta:{};
  const apkType=String(meta.apkType||meta.modInfo||'APK').trim()||'APK';
  const playStore=safeUrl(meta.playStoreUrl);
  const direct=safeUrl(meta.directDownloadUrl);
  const downloadPage=safeUrl(meta.downloadPageUrl);
  const shots=Array.isArray(meta.screenshots)?meta.screenshots.filter(Boolean).slice(0,24):[];
  const hasIcon=Boolean(meta.iconUrl);
  const rating=meta.ratingValue==null?'Not reported':`${esc(meta.ratingValue)}/5`;
  const downloadText=x.downloadCount==null?'Not reported':esc(count(x.downloadCount));
  const screenshots=shots.length
    ? `<div class="apk-screenshot-grid">${shots.map((_,i)=>`<a class="apk-shot" href="/api/software/${x.id}/android-assets/screenshot/${i}" title="Download screenshot ${i+1}"><img src="/api/software/${x.id}/android-assets/screenshot/${i}?inline=1" loading="lazy" alt="${esc(x.name)} screenshot ${i+1}"><span>Screenshot ${i+1}</span></a>`).join('')}</div>`
    : '<div class="empty compact-empty">No screenshots were found for this APK.</div>';
  $('#modalWrap').innerHTML=`<div class="modal detail-modal android-detail-modal">
    <div class="modal-head">
      <div class="modal-title-row"><div style="min-width:0"><div class="sw-title-line"><div class="detail-title">${esc(x.name)}</div><span class="code">v${esc(x.version||'—')}</span><span class="status ${x.published?'published':'draft'}">${x.published?'Published':'Draft'}</span>${x.claim?`<span class="status claim-own">In progress · ${Number(x.claim.userId)===Number(S.data?.user?.id)?'You':esc(x.claim.name)}</span>`:''}${x.updateAvailable?`<span class="status update">Update ${esc(x.latestVersion)}</span>`:''}</div><div class="cat-meta">Android APK · ${esc(apkType)}</div></div></div>
      <div class="form-row detail-actions"><button class="btn tiny copy-all" id="copyAllDetails">Copy Details</button><button class="btn tiny ${x.published?'':'success'}" id="modalPublish">${x.published?'Unpublish':'Publish'}</button><button class="btn tiny" id="refreshDetails">Refresh</button><button class="btn icon-btn" id="closeModal" aria-label="Close">${icon('close')}</button></div>
    </div>
    <div class="modal-body"><main style="min-width:0">
      ${x.backgroundStatus==='running'||x.enrichmentStatus==='fetching'?`<div class="notice amber compact-notice"><b>Refreshing APK details.</b> Current values stay visible while HSWare checks the Android source.</div>`:''}
      ${x.updateAvailable?`<div class="notice amber compact-notice"><b>${meta.updateReason==='size'?'APK file size changed':meta.updateReason==='download-page'?'APK download target changed':`APK update ${esc(x.version)} → ${esc(x.latestVersion||'new version')}`}</b><div class="form-row"><button class="btn tiny primary" id="markUpdated">Mark updated</button></div></div>`:''}

      <div class="android-detail-layout">
        <section class="android-detail-main">
          <h3 class="section-title">APK Details</h3>
          <div class="fields android-fields">
            ${field('App Name',esc(x.name))}
            ${field('Version',esc(x.version||'Not reported'))}
            ${field('App Size',bytes(x.fileSizeBytes))}
            ${field('Requires Android',esc(x.minimumOsVersion||'Not reported'))}
            ${field('APK License / Type',esc(apkType))}
            ${field('User Rating',rating)}
            ${field('Downloads',downloadText)}
          </div>

          <h3 class="section-title section-gap">App Links</h3>
          <div class="fields android-link-fields">
            ${field('Original App Link',playStore?playStore:'Not available',playStore||'')}
            ${field('Direct Download Link',direct?direct:(downloadPage?'Resolver pending':'Not available'),direct||'')}
          </div>
          <div class="helper apk-direct-note">HSWare stores a resolved direct APK/XAPK/APKS file URL when one is available. The LiteAPKs source page is not used as the final download link.</div>
        </section>

        <aside class="apk-media-card">
          <div class="apk-media-head"><div><div class="section-title" style="margin:0">APK Media</div><div class="helper">Real downloadable image files, not external image links.</div></div></div>
          <div class="apk-icon-wrap">${hasIcon?`<img class="apk-icon-preview" src="/api/software/${x.id}/android-assets/icon?inline=1" alt="${esc(x.name)} icon">`:`<div class="apk-icon-empty">No icon</div>`}</div>
          <div class="apk-media-actions">
            ${hasIcon?`<a class="btn" href="/api/software/${x.id}/android-assets/icon">Download Icon</a>`:''}
            ${hasIcon||shots.length?`<a class="btn primary" href="/api/software/${x.id}/android-assets.zip">Download Media ZIP</a>`:''}
          </div>
          <div class="helper">${hasIcon?'1 icon':'No icon'} · ${shots.length} screenshot${shots.length===1?'':'s'} available</div>
        </aside>
      </div>

      <div class="section-heading-row"><h3 class="section-title" style="margin:0">Screenshots</h3>${shots.length?`<a class="btn tiny primary" href="/api/software/${x.id}/android-assets.zip">Download All</a>`:''}</div>
      ${screenshots}
      <div id="detailMsg"></div>
    </main></div>
  </div>`;
  $('#closeModal').onclick=closeDetail;
  $('#copyAllDetails').onclick=()=>copyText(allDetailsText(x));
  $('#refreshDetails').onclick=async()=>{const b=$('#refreshDetails');b.disabled=true;b.textContent='Queuing…';try{await API(`/api/software/${x.id}/refresh`,{method:'POST',body:'{}'});toast('APK details refresh started');const fresh=await API(`/api/software/${x.id}`);S.detail=fresh.software;renderDetail();const token=++S.detailPollToken;pollDetail(x.id,token)}catch(e){toast(e.message)}finally{if(document.body.contains(b)){b.disabled=false;b.textContent='Refresh'}}};
  if($('#resolveApkDownload'))$('#resolveApkDownload').onclick=async()=>{const b=$('#resolveApkDownload');const popup=window.open('about:blank','_blank');b.disabled=true;b.textContent='Refreshing link…';try{const d=await API(`/api/software/${x.id}/android-download/resolve`,{method:'POST',body:'{}'});if(popup)popup.location.href=d.url;else window.location.href=d.url;toast(d.mode==='direct'?'Current direct APK link opened':'Current LiteAPKs download page opened')}catch(e){if(popup)popup.close();toast(e.message,'error')}finally{if(document.body.contains(b)){b.disabled=false;b.textContent='Download APK'}}};
  $('#modalPublish').onclick=async()=>{await API(`/api/software/${x.id}/toggle-published`,{method:'POST',body:'{}'});toast(x.published?'Moved to New APK':'Moved to Published APK');await closeDetail({release:false});await refreshBootstrap();await go(S.tab)};
  $('#markUpdated')&&($('#markUpdated').onclick=async()=>{try{await API(`/api/software/${x.id}/mark-updated`,{method:'POST',body:'{}'});toast('APK version marked updated');const fresh=await API(`/api/software/${x.id}`);S.detail=fresh.software;renderDetail();await refreshBootstrap()}catch(e){toast(e.message)}});
}

function renderDetail(){
  const x=S.detail;
  if(isLiteApks(x))return renderAndroidDetail(x);
  const official=safeUrl(x.officialUrl),installer=safeUrl(x.installerUrl),latest=safeUrl(x.latestInstallerUrl),source=safeUrl(x.sourcePageUrl),android=isLiteApks(x);
  const autoUsed=Object.values(x.requirementEstimates||{}).some(Boolean);
  const sourceMeta=x.sourceMeta&&typeof x.sourceMeta==='object'?x.sourceMeta:{};
  const sourceLabels=android&&sourceMeta.labels&&typeof sourceMeta.labels==='object'?Object.entries(sourceMeta.labels).slice(0,80):[];
  const sourceLabelFields=sourceLabels.map(([k,v])=>field(String(k).replace(/\b\w/g,c=>c.toUpperCase()),esc(v))).join('');
  const screenshotLinks=android&&Array.isArray(sourceMeta.screenshots)?sourceMeta.screenshots.map((u,i)=>safeUrl(u)?`<a class="btn tiny" href="${esc(safeUrl(u))}" target="_blank" rel="noreferrer">Screenshot ${i+1}</a>`:'').filter(Boolean).join(' '):'';
  const versions=x.versions?.length?x.versions.slice(0,5).map(v=>`<div class="version-row"><div><div class="field-label">Version</div><b>${esc(v.version)}</b></div><div><div class="field-label">Updated</div><b>${esc(dateLabel(v.updatedDate))}</b></div><div>${!android&&v.installerUrl?`<button class="btn tiny primary" data-copy="${esc(v.installerUrl)}">Copy Link</button>`:android&&source?`<a class="btn tiny" href="${esc(source)}" target="_blank" rel="noreferrer">Source</a>`:'<span class="muted-value">N/A</span>'}</div></div>`).join(''):`<div class="empty compact-empty">${android?'No older LiteAPKs version metadata available.':'No older WinGet version available.'}</div>`;
  $('#modalWrap').innerHTML=`<div class="modal detail-modal">
    <div class="modal-head">
      <div class="modal-title-row"><div style="min-width:0"><div class="sw-title-line"><div class="detail-title">${esc(x.name)}</div><span class="code">v${esc(x.version||'—')}</span><span class="status ${x.published?'published':'draft'}">${x.published?'Published':'Draft'}</span><span class="status quality">${Number(x.completeness||0)}% Ready</span>${x.claim?`<span class="status claim-own">In progress · ${Number(x.claim.userId)===Number(S.data?.user?.id)?'You':esc(x.claim.name)}</span>`:''}${x.updateAvailable?`<span class="status update">Update ${esc(x.latestVersion)}</span>`:''}</div><div class="cat-meta">${esc(packageDisplay(x))} · ${esc(platformLabel(x))} · ${esc(x.sourceType==='liteapks'?'LiteAPKs':'WinGet')} · ${esc(x.category||'Uncategorized')}</div></div></div>
      <div class="form-row detail-actions"><button class="btn tiny copy-all" id="copyAllDetails">Copy All</button><button class="btn tiny ${x.published?'':'success'}" id="modalPublish">${x.published?'Unpublish':'Publish'}</button><button class="btn tiny" id="refreshDetails">Refresh</button><button class="btn tiny" id="forkSoftware">Fork</button><button class="btn icon-btn" id="closeModal" aria-label="Close">${icon('close')}</button></div>
    </div>
    <div class="modal-body"><main style="min-width:0">
      ${x.backgroundStatus==='running'||x.enrichmentStatus==='fetching'?`<div class="notice amber compact-notice"><b>Refreshing details in the background.</b> Current values stay available while HSWare checks the source.</div>`:''}
      ${x.updateAvailable?`<div class="notice amber compact-notice"><b>Update ${esc(x.version)} → ${esc(x.latestVersion)}</b><div class="inline-update">${esc(android?(source||'LiteAPKs source page'):(latest||'Installer URL pending'))}</div><div class="form-row">${android&&source?`<button class="btn tiny" data-copy="${esc(source)}">Copy source</button>`:latest?`<button class="btn tiny" data-copy="${esc(latest)}">Copy new link</button>`:''}<button class="btn tiny primary" id="markUpdated">Mark updated</button></div></div>`:''}
      <div class="workspace-summary"><div><span>Readiness</span><b>${Number(x.completeness||0)}%</b></div><div><span>Imported</span><b>${x.importedAt?esc(new Date(x.importedAt).toLocaleDateString()):'—'}</b></div><div><span>Details</span><b>${x.enrichmentStatus==='ready'?'Ready':x.enrichmentStatus==='error'?'Retry available':'Automatic'}</b></div><div><span>Previous Versions</span><b>${fmt(x.versions?.length||0)}</b></div><div><span>Architecture</span><b>${esc(x.architecture||'—')}</b></div><div><span>Installer</span><b>${esc(x.installerType||'—')}</b></div></div>

      <h3 class="section-title">Software Details</h3>
      <div class="fields detail-grid">
        ${field('Software Name',esc(x.name))}
        ${field('Developer',esc(x.developer||x.publisher||'N/A'))}
        ${field('Publisher',esc(x.publisher||x.developer||'N/A'))}
        ${field('Category',esc(x.category||'Uncategorized'))}
        ${field(android?'Android Package / LiteAPKs ID':'WinGet Package ID',`<span class="code clipped-code" title="${esc(packageDisplay(x))}">${esc(packageDisplay(x))}</span>`,packageDisplay(x))}
        ${field('Current Version',esc(x.version||'Pending'))}
        ${field('File Size',bytes(x.fileSizeBytes))}
        ${field('License',esc(x.licenseName||'N/A'))}
        ${field('Language',esc(languageLabel(x.language)),'',estimateMark(x,'language'))}
        ${field('Downloads',x.downloadCount==null?'Not reported':esc(count(x.downloadCount)))}
        ${field('Architecture',esc(x.architecture||'Universal'))}
        ${field('Installer Type',esc(x.installerType||'Standard installer'))}
      </div>

      <h3 class="section-title section-gap">System Requirements</h3>
      <div class="fields requirement-grid">
        ${field('Platform',esc(platformLabel(x)),'',estimateMark(x,'platform'))}
        ${field('Minimum OS',esc(osLabel(x.minimumOsVersion)),'',estimateMark(x,'minimumOsVersion'))}
        ${field('Processor',esc(processorLabel(x)),'',estimateMark(x,'processor'))}
        ${field('RAM',esc(requirementValue(x,x.ramRequirement)),'',estimateMark(x,'ram'))}
        ${field('Storage',esc(storageLabel(x.storageRequirement)),'',estimateMark(x,'storage'))}
        ${field('Graphics',esc(requirementValue(x,x.graphicsRequirement)),'',estimateMark(x,'graphics'))}
      </div>
      ${autoUsed?`<div class="estimate-note"><span class="field-meta auto">Auto</span> HSWare fills practical minimums when the publisher does not publish one. Official values always take priority.</div>`:''}
      ${x.requirementsSourceUrl?`<div class="source-line">Official requirements source: <a href="${esc(safeUrl(x.requirementsSourceUrl))}" target="_blank" rel="noreferrer">Open source ↗</a></div>`:''}${android&&x.sourceUpdatedAt?`<div class="source-line">LiteAPKs page updated: <b>${esc(dateLabel(x.sourceUpdatedAt))}</b></div>`:''}

      ${android?`<h3 class="section-title section-gap">LiteAPKs Source Metadata</h3><div class="fields detail-grid">${field('MOD Info',esc(sourceMeta.modInfo||'Not reported'))}${field('Price',esc(sourceMeta.price||'Not reported'))}${field('Rating',sourceMeta.ratingValue==null?'Not reported':esc(sourceMeta.ratingValue))}${field('Icon URL',safeUrl(sourceMeta.iconUrl)?`<a href="${esc(safeUrl(sourceMeta.iconUrl))}" target="_blank" rel="noreferrer">Open icon ↗</a>`:'Not reported',safeUrl(sourceMeta.iconUrl))}${sourceLabelFields}</div>${screenshotLinks?`<div class="source-line"><b>Screenshot metadata:</b> ${screenshotLinks}</div>`:''}`:''}

      <h3 class="section-title section-gap">Links & Package Integrity</h3>
      <div class="fields link-grid">
        ${field('Official Website',official?`<a href="${esc(official)}" target="_blank" rel="noreferrer">Open website ↗</a>`:'N/A',official)}
        ${android?field('LiteAPKs Source Page',source?`<a href="${esc(source)}" target="_blank" rel="noreferrer">Open LiteAPKs ↗</a>`:'N/A',source):field('Direct Download',installer?`<a href="${esc(installer)}" target="_blank" rel="noreferrer">Open installer ↗</a>`:'Pending',installer)}
        ${android?field('APK Binary','Not mirrored by HSWare'):field('SHA-256',x.sha256?`<span class="code hash-code hash-preview" title="${esc(x.sha256)}">${esc(String(x.sha256).slice(0,3))}…</span>`:'N/A',x.sha256||'')}
      </div>

      <div class="description-details"><div class="description-label">Description</div><div class="desc description-clamp">${esc(x.description||'Description unavailable from the current package source.')}</div></div>

      <div class="section-heading-row"><h3 class="section-title" style="margin:0">Previous Versions</h3><button class="btn tiny" id="copyOldVersions">Copy Old Versions</button></div>
      <div class="versions compact-versions">${versions}</div>
      <div id="detailMsg"></div>
    </main></div>
  </div>`;
  $('#closeModal').onclick=closeDetail;
  $('#copyAllDetails').onclick=()=>copyText(allDetailsText(x));
  $('#forkSoftware').onclick=async()=>{const snapshot={packageId:packageDisplay(x),sourceType:x.sourceType,platform:platformLabel(x),sourcePageUrl:safeUrl(x.sourcePageUrl),name:x.name,version:x.version,publisher:x.publisher,architecture:x.architecture,installerType:x.installerType,officialUrl:safeUrl(x.officialUrl),installerUrl:android?null:safeUrl(x.installerUrl),sha256:android?null:x.sha256};await copyText(JSON.stringify(snapshot,null,2));toast('Software fork snapshot copied')};
  $('#copyOldVersions').onclick=()=>copyText((x.versions||[]).slice(0,5).map((v,i)=>`${i+1}. Version: ${v.version}${android?'':`\nDownload Link: ${safeUrl(v.installerUrl)||'N/A'}`}\nUpdated: ${dateLabel(v.updatedDate)}`).join('\n\n')||'No previous versions available.');
  $('#refreshDetails').onclick=async()=>{const b=$('#refreshDetails');b.disabled=true;b.textContent='Queuing…';try{await API(`/api/software/${x.id}/refresh`,{method:'POST',body:'{}'});toast('Details refresh started');const fresh=await API(`/api/software/${x.id}`);S.detail=fresh.software;renderDetail();const token=++S.detailPollToken;pollDetail(x.id,token)}catch(e){toast(e.message)}finally{if(document.body.contains(b)){b.disabled=false;b.textContent='Refresh'}}};
  $('#modalPublish').onclick=async()=>{await API(`/api/software/${x.id}/toggle-published`,{method:'POST',body:'{}'});toast(x.published?`Moved to ${android?'New APK':'New Software'}`:`Moved to ${android?'Published APK':'Published Software'}`);await closeDetail({release:false});await refreshBootstrap();await go(S.tab)};
  $('#markUpdated')&&($('#markUpdated').onclick=async()=>{try{await API(`/api/software/${x.id}/mark-updated`,{method:'POST',body:'{}'});toast('HSWare version marked updated');const fresh=await API(`/api/software/${x.id}`);S.detail=fresh.software;renderDetail();await refreshBootstrap()}catch(e){toast(e.message)}});
  $('#modalWrap').querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyText(b.dataset.copy));
}
async function healthModal(){if(!isAdmin())return toast('Database Health is available to the Admin only');document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="healthWrap"><div class="modal" style="max-width:640px"><div class="modal-head"><div class="detail-title" style="font-size:16px">System Health</div><button class="btn icon-btn" id="healthClose" aria-label="Close">${icon('close')}</button></div><div class="panel-body" id="healthBody">Loading…</div></div></div>`);$('#healthClose').onclick=()=>$('#healthWrap').remove();try{const d=await API('/api/health');$('#healthBody').innerHTML=`<div class="health-list">${d.checks.map(c=>`<div class="health-row"><span class="health-dot ${c.status==='fail'?'fail':c.status==='recommend'?'recommend':''}"></span><div><div style="font-size:13px;font-weight:700">${esc(c.name)}</div><div class="helper" style="margin:2px 0 0">${esc(c.detail)}</div></div></div>`).join('')}</div>`}catch(e){$('#healthBody').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function init(){try{await bootstrap();shell();if(isAdmin())startBackupNotificationPoll();startWorkClaimPoll();startNotificationPoll();window.addEventListener('pagehide',releaseDetailOnPageExit);await go('dashboard')}catch(e){app.innerHTML=`<div class="boot"><div><b>HSWare could not load.</b><div style="margin-top:8px;color:#991B1B">${esc(e.message)}</div></div></div>`}}
init();
})();
